import csv, collections
with open('outputs/t11_city_indicator_matrix.csv', newline='', encoding='utf-8') as f:
    r = list(csv.reader(f))
print(len(r), r[0])
toks=collections.Counter()
for row in r[1:]:
    for v in row[3:]:
        if v=='' or not v.replace('.','',1).replace('-','',1).isdigit():
            toks[v]+=1
print(toks.most_common(20))
print('rows width:', set(len(row) for row in r))
EOF"}
